{"cmd":"python3 - <<'PY'
import pdfplumber
import pandas as pd
import json
import re

pdf_path = '/root/employees_backup.pdf'
xlsx_path = '/root/employees_current.xlsx'

# Extract PDF tables
rows = []
header = None
with pdfplumber.open(pdf_path) as pdf:
    for page in pdf.pages:
        tables = page.extract_tables()
        if not tables:
            continue
        for table in tables:
            for row in table:
                if not row or all((c is None or str(c).strip()=='') for c in row):
                    continue
                # normalize row length
                row = ["" if c is None else str(c).strip() for c in row]
                if header is None:
                    header = row
                    continue
                # skip repeated header rows
                if [c.strip() for c in row] == [c.strip() for c in header]:
                    continue
                rows.append(row)

if header is None:
    raise SystemExit('No header found in PDF')

old_df = pd.DataFrame(rows, columns=header)

# Clean columns
old_df.columns = [c.strip() for c in old_df.columns]

# strip whitespace from text columns
for col in old_df.columns:
    old_df[col] = old_df[col].astype(str).str.strip()

# numeric columns
for col in ['Salary', 'Years', 'Score']:
    if col in old_df.columns:
        old_df[col] = (
            old_df[col]
            .str.replace(',', '', regex=False)
            .replace({'': None})
        )
        old_df[col] = pd.to_numeric(old_df[col], errors='coerce')

# Load current Excel
new_df = pd.read_excel(xlsx_path, engine='openpyxl', dtype={'ID': str})
new_df.columns = [c.strip() for c in new_df.columns]
for col in new_df.columns:
    if new_df[col].dtype == object:
        new_df[col] = new_df[col].astype(str).str.strip()

# Ensure numeric columns
for col in ['Salary', 'Years', 'Score']:
    if col in new_df.columns:
        new_df[col] = pd.to_numeric(new_df[col], errors='coerce')

# Set index
old_df = old_df.set_index('ID')
new_df = new_df.set_index('ID')

old_ids = set(old_df.index)
new_ids = set(new_df.index)

deleted = sorted(old_ids - new_ids)

modified = []
common_ids = sorted(old_ids & new_ids)

for emp_id in common_ids:
    old_row = old_df.loc[emp_id]
    new_row = new_df.loc[emp_id]
    for field in old_df.columns:
        old_val = old_row[field]
        new_val = new_row[field] if field in new_row.index else None
        # treat NaN equality
        if pd.isna(old_val) and pd.isna(new_val):
            continue
        if isinstance(old_val, float) and isinstance(new_val, float):
            if pd.isna(old_val) and pd.isna(new_val):
                continue
        if old_val != new_val:
            # normalize types for JSON (convert numpy types)
            if pd.isna(old_val):
                old_val_out = None
            else:
                old_val_out = old_val.item() if hasattr(old_val, 'item') else old_val
            if pd.isna(new_val):
                new_val_out = None
            else:
                new_val_out = new_val.item() if hasattr(new_val, 'item') else new_val
            modified.append({
                'id': emp_id,
                'field': field,
                'old_value': old_val_out,
                'new_value': new_val_out,
            })

# sort modified by id then field for consistency
modified_sorted = sorted(modified, key=lambda x: (x['id'], x['field']))

report = {
    'deleted_employees': deleted,
    'modified_employees': modified_sorted,
}

with open('/root/diff_report.json', 'w') as f:
    json.dump(report, f, indent=2)

print('deleted', len(deleted))
print('modified', len(modified_sorted))
